{"file_path":"sales_dashboard/loader.py","content":""""Product analytics dashboard: customer-session log loading and aggregation."""


def parse_session_log(lines):
    """Parse session log lines into session dictionaries.

    Blank lines and comment lines are ignored. Invalid records raise ``ValueError``
    with the input line number included in the message.
    """
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = line.split(",")
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, converted_text = (field.strip() for field in fields)
        try:
            day = int(day_text)
        except ValueError as error:
            raise ValueError(f"line {line_number}: day must be an integer") from error

        if converted_text == "1":
            converted = True
        elif converted_text == "0":
            converted = False
        elif converted_text == "":
            converted = None
        else:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "converted": converted})
    return out


def dedupe_sessions(events):
    """Keep the last record for each id and sort by day, then id."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Count converted sessions for each day in the inclusive requested range."""
    if end_day < start_day:
        return []

    counts = {day: 0 for day in range(start_day, end_day + 1)}
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["converted"] is True:
            counts[day] += 1
    return [counts[day] for day in range(start_day, end_day + 1)]
